package preferences
import "testing"
func TestPreferencesAndRootIsolation(t *testing.T){dir:=t.TempDir();s,e:=New(dir);if e!=nil{t.Fatal(e)};p:=s.Get("A").Preferences;if p.Theme!="dark"||!p.Grouped{t.Fatal("default view must be dark and grouped")};p.Theme="light";p.Palette="ocean";p.Speed=1.5;if e=s.Set(p);e!=nil{t.Fatal(e)};if e=s.Bind("A",map[string]Contact{"hash":{Name:"设计讨论",Username:"group-id",Type:"group"}});e!=nil{t.Fatal(e)};if len(s.Get("B").Contacts)!=0{t.Fatal("account bindings leaked between source roots")};s2,e:=New(dir);if e!=nil{t.Fatal(e)};if s2.Get("A").Preferences.Speed!=1.5||s2.Get("A").Contacts["hash"].Name!="设计讨论"{t.Fatal("preferences or bindings lost on restart")};if e=s.Bind("A",map[string]Contact{"bad":{Name:"bad",Type:"invalid"}});e==nil{t.Fatal("invalid binding accepted")};if len(s.Get("A").Contacts)!=1{t.Fatal("failed import changed bindings")};p.Volume=2;if e=s.Set(p);e==nil{t.Fatal("invalid volume accepted")};if s.Get("A").Preferences.Volume==2{t.Fatal("invalid settings changed saved state")};if e=s.Bind("A",map[string]Contact{"hash":{Type:"custom"}});e!=nil{t.Fatal(e)};if len(s.Get("A").Contacts)!=0{t.Fatal("unbind failed")}}
